struct CodeToken: Identifiable, Equatable {
    let id: Int
    let text: String
    let kind: CodeTokenKind
    var isInteractive: Bool { kind == .identifier || kind == .typeName }
}

enum CodeTokenizer {
    private static let keywords: Set<String> = [
    // 함수 2개 — 각각 별도 노드
