@Observable @MainActor final class GraphGestureController {
    var root: Entity?
    private(set) var mode: Mode = .none
    private var committedScale: Float = 1
    private var committedOrientation = simd_quatf(angle: 0, axis: [0, 1, 0])
    private var committedPosition: SIMD3<Float> = .zero
    private let magnifyThreshold: Float = 0.06
    private let rotateThreshold: Float = .pi / 30
    // 함수 7개 — 각각 별도 노드
}

enum Mode {
    case none, magnify, rotate, drag
}

func dragChanged(_ translation: Vector3D) {
    guard let root else { return }
    if mode == .none {
        mode = .drag
        committedPosition = root.position
    }
    guard mode == .drag else { return }
    let meters = SIMD3<Float>(
        Float(translation.x),
        -Float(translation.y),   // SwiftUI는 +y가 아래, RealityKit은 +y가 위
        Float(translation.z)
    ) / SceneStyle.pointsPerMeter
    root.position = committedPosition + meters
}

func dragEnded() {
    guard mode == .drag else { return }
    mode = .none
}

func magnifyChanged(_ magnification: Float) {
    guard let root else { return }
    if mode == .none, abs(magnification - 1) > magnifyThreshold {
        mode = .magnify
        committedScale = root.scale.x
    }
    guard mode == .magnify else { return }
    root.scale = SIMD3(repeating: max(0.2, min(5, committedScale * magnification)))
}

func magnifyEnded() {
    guard mode == .magnify else { return }
    mode = .none
}

private func realityKitQuaternion(from rotation: Rotation3D) -> simd_quatf {
    let q = rotation.quaternion
    return simd_normalize(simd_quatf(
        ix: -Float(q.imag.x),
        iy: Float(q.imag.y),
        iz: -Float(q.imag.z),
        r: Float(q.real)
    ))
}

func rotateChanged(_ rotation: Rotation3D) {
    guard let root else { return }
    let delta = realityKitQuaternion(from: rotation)
    if mode == .none, abs(delta.angle) > rotateThreshold {
        mode = .rotate
        committedOrientation = root.orientation
    }
    guard mode == .rotate else { return }
    // 제스처 회전은 사용자(세계) 기준 프레임에서 주어지므로, 기존 회전 앞에 곱해(pre-multiply)
    // 그래프가 현재 어떤 자세이든 손이 도는 방향 그대로 돌게 한다.
    root.orientation = simd_normalize(delta * committedOrientation)
}

func rotateEnded() {
    guard mode == .rotate else { return }
    mode = .none
}

struct GraphGesturesModifier: ViewModifier {
    let controller: GraphGestureController
    // 함수 1개 — 각각 별도 노드
}

func body(content: Content) -> some View {
    content
        .simultaneousGesture(
            MagnifyGesture()
                .onChanged { controller.magnifyChanged(Float($0.magnification)) }
                .onEnded { _ in controller.magnifyEnded() }
        )
        .simultaneousGesture(
            RotateGesture3D(constrainedToAxis: nil, minimumAngleDelta: .degrees(2))
                .onChanged { controller.rotateChanged($0.rotation) }
                .onEnded { _ in controller.rotateEnded() }
        )
        .simultaneousGesture(
            DragGesture(minimumDistance: 30, coordinateSpace: .immersiveSpace)
                .onChanged { controller.dragChanged($0.translation3D) }
                .onEnded { _ in controller.dragEnded() }
        )
}

struct GraphIndex: Sendable {
    let nodesByID: [String: CodeNode]
    private let childrenByParent: [String: [CodeNode]]
    let outgoing: [String: [CodeEdge]]
    let incoming: [String: [CodeEdge]]
    let referencingNodes: [String: Set<String>]
    let roots: [CodeNode]
    // 함수 5개 — 각각 별도 노드
}

func ancestors(of id: String) -> [String] {
    var result: [String] = []
    var current = nodesByID[id]?.parentID
    while let parent = current, !result.contains(parent) {
        result.append(parent)
        current = nodesByID[parent]?.parentID
    }
    return result
}

func descendantCount(of id: String) -> Int {
    children(of: id).reduce(0) { $0 + 1 + descendantCount(of: $1.id) }
}

func hasChildren(_ id: String) -> Bool {
    !(childrenByParent[id]?.isEmpty ?? true)
}

init(graph: CodeGraph) {
    nodesByID = Dictionary(graph.nodes.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })

    var children: [String: [CodeNode]] = [:]
    var roots: [CodeNode] = []
    for node in graph.nodes {
        if let parentID = node.parentID, nodesByID[parentID] != nil {
            children[parentID, default: []].append(node)
        } else {
            roots.append(node)
        }
    }
    childrenByParent = children.mapValues { siblings in
        siblings.sorted { a, b in
            switch (a.line, b.line) {
            case let (la?, lb?) where la != lb: la < lb
            case (nil, .some): false
            case (.some, nil): true
            default: a.name < b.name
            }
        }
    }
    self.roots = roots.sorted { $0.id < $1.id }

    var outgoing: [String: [CodeEdge]] = [:]
    var incoming: [String: [CodeEdge]] = [:]
    for edge in graph.edges {
        outgoing[edge.from, default: []].append(edge)
    // … 12줄 생략
}

enum GraphLoader {
    private static let logger = Logger(subsystem: "CodeSpace", category: "GraphLoader")
    static let indexedResourceName = "CodeSpaceGraph"
    static let sampleResourceName = "SampleGraph"
    // 함수 3개 — 각각 별도 노드
}

private static func load(resourceNamed name: String) -> CodeGraph? {
    guard let url = Bundle.main.url(forResource: name, withExtension: "json") else {
        logger.notice("\(name).json이 번들에 없습니다.")
        return nil
    }
    do {
        let data = try Data(contentsOf: url)
        let graph = try parse(data: data)
        logger.info("\(name).json 로드 성공: 노드 \(graph.nodes.count)개, 엣지 \(graph.edges.count)개")
        return graph
    } catch {
        logger.error("\(name).json 로드/파싱 실패: \(error.localizedDescription)")
        return nil
    }
}

static func loadBundledGraph() -> CodeGraph {
    for name in [indexedResourceName, sampleResourceName] {
        if let graph = load(resourceNamed: name) { return graph }
    }
    logger.error("번들 그래프를 하나도 읽지 못했습니다. CodeGraph.sample로 대체합니다.")
    return .sample
}

static func parse(data: Data) throws -> CodeGraph {
    try JSONDecoder().decode(CodeGraph.self, from: data)
}

